from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from django.contrib.sites.shortcuts import get_current_site
from .models import NewsletterSubscriber

class NewsletterUnsubscribeView(APIView):
    def post(self, request):
        subscriber_hash = request.data.get('subscriber_hash')
        current_site = get_current_site(request)
        subscriber = NewsletterSubscriber.objects.filter(token=subscriber_hash, site=current_site).first()
        if not subscriber:
            return Response({'error': 'Subscriber not found for this domain'}, status=status.HTTP_404_NOT_FOUND)

        subscriber.is_active = False
        subscriber.save(update_fields=['is_active'])
        return Response({'message': 'Unsubscribed successfully'})
